uv3.y = uv3.y  +0.08*time ;
//uv3.y = uv3.y + time/32;
uv3.x = uv3.x  + time/32;
//uv3.x = uv3.x +0.08*time;

float3 crisp = 2*GetPixel(uv2) + GetPixel(uv3);
crisp += 2*GetBlur2(frac(uv2)) + 2*GetBlur2(frac(uv3));

float3 lay1 = float3 (0,0,0)*uv.y*pow(1-rad,8);

