float2 uv1,uv2,uv3,uv4,uv5,rsk,dz1,Kugel1;
float stone, ray1, sun1, rad1, mask2, mask1, trel;
float3 light;
static float2 lpos1 = float2(q13,q14);
static const float iter6 =1;
static const float clip1 = (rand_preset.x >= .5)+1;

 float2 cpow(float2 base, float ex) {
   float moduz = sqrt(base.x*base.x + base.y*base.y);
   float thetaz = atan2(base.y, base.x);
   float2 pow = float2(pow(moduz, ex)*cos(thetaz*ex), pow(moduz, ex)*sin(thetaz*ex));
   return pow; }

shader_body
{
uv1 = float2(uv.x-.5,uv.y-0.5)*aspect.xy;

//STONE
float dist = 40+18*iter6;
uv3 = dist * (uv1) + dist*float2(0,sin(q15))*0;
float ky = saturate(.04-uv3.y/40);
float k1 = uv3.x ;;
k1 = k1 - sign (k1)*14; //Verdoppelung
k1 = k1 - sign (k1)*q28*2; //Verdoppelung
k1 = k1 - sign (k1)*8; //Verdoppelung

float ff = 16 + 16*rand_preset.z;
int n = 1 ;
while (n <= 4+2*iter6) 
{
  k1 += (-ff*n*sign(k1))*ky*ky;
  ky = saturate (ky - .1);
  n++; 
}
k1 = clamp(k1,-1.57,1.57);
stone = saturate(cos(k1)-.02) ;

light = 0; trel = time*.2;
for (int m= 1; m<= 3; m++)
{//Kugel1
  rsk = (uv1 + .3*float2 (cos(q15/m)*(m%2),cos(q16/m)*((m+1)%2))) ;
  dz1 = normalize(rsk);
  rad1 = 16*length (rsk) * (2+cos(q17*m)) ;
  uv4 =  tan(rad1)*dz1;
  mask1 = saturate(9-7*rad1);
  Kugel1 = uv4*mask1;
  light += (.1/rad1)*pow(q23,1+slow_roam_sin);;
  uv=  uv+Kugel1*.1;
}

uv+=stone*.05;
//Fractal Distortion
float2 z = (uv.yx-.5)*(2+stone);
float2 uv2 = cpow(z,.5+.3*q28/8)%clip1;

uv2 = 0.5 + (1.0 -abs(frac(uv2 * 0.5)*2 - 1.0 )-0.5)*1; // Eo.S. mirror code
ret = (tex2D(sampler_main, uv2.yx) + GetPixel(uv_orig))*.46;
//ret += .002/length(uv1);

//LASER
uv4 = uv-.5-lpos1+stone;
uv5  = normalize(uv4)-float2(q10,q11);
ray1 = saturate (1-length(uv5/q12));
ray1 += pow(.001/length(uv5),1)/length(uv4);
sun1 = saturate(.002/length(uv4))/(1.05-q12);

ret += (ray1+sun1)*.8*frac(float3(q27,q27+3,q27+6)/16);
ret += (.02/length(sin(uv2*2+.2*(q27%8-4))));
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv2.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y -= (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z -= (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x -= (noise9).z*.5; 
ret += pow(stone,3)*q29*(1+roam_sin);
ret += light;
ret *= 1-.08*30/fps;
}

