float3 ret1, window;
float2 rsk, uv1, uv2, uv3, uv4, dz1, Kugel1;
float mask1, rad1, rill, stone;
static float iter6 = (rand_preset.z > .5);
shader_body {

float dx = abs(.5-frac(uv.x*88))*0;
float dy = abs(.5-frac(uv.y*88))*1;
uv += float2(dx,dy)*.0;

uv1 = float2(uv.x-.5,uv.y-0.5);

float2 uv3 = uv1;float dist = 42.5+18*iter6;
uv3 = dist * uv1;

