k1 = k1 - sign (k1)*(2+rand_preset.y*8); //Verdoppelung

float ff = 16 + 16*rand_preset.z;
int n = 1 ;
float delta = .1;
while (n <= 4+2*iter6) 
{
  k1 += (-ff*n*sign(k1))*ky*ky;
  ky = saturate (ky - delta);
  delta *= 1;
  n++; 
}
float k2 = k1;
k1 = clamp(k1,-1.57,1.57);
stone = saturate(cos(time+k1)-.02);

rill = (rand_preset-.5)*(cos(8*k2))*stone;

ret1 = pow(stone,1)*float3(1,.86,.74)+rill;
float noise = tex2D (sampler_noise_lq,uv/8);
noise *= (noise <= .2)*2;
ret = max(ret1,0*(GetPixel((uv_orig+float2(.5,.5)))-.1)) - noise;
ret*=2.1;
}

