//mirror code by flexi
float2 uv2 =(6+2*roam_sin)*float2(1-uv.x,uv.y)-roam_sin;
float2 m = floor(frac(uv2*0.5)*2);
uv2 = frac(uv2)*(1-m) + (m)*frac(1-uv2);

//texture/drop shadow code by Geiss
    float3 tex = .2+GetBlur1(uv2).yzx;
