sampler sampler_pw_noise_lq;
float3 ret1;
shader_body {
float corr = texsize.xy*texsize_noise_lq.zw;
float2 uv1 = float2(uv.x-0.5,uv.y-0.5)*aspect.xy;


float3 noiseVal = lum(tex2D(sampler_noise_lq, corr*uv*.5+ .1*rand_frame));

float2 hor = float2 (.005,0.007);
float2 ver = float2 (-0.007,.005);

float f0 = 1;
float dx = f0*lum(tex2D(sampler_main,uv+hor) 
         - tex2D(sampler_main,uv-hor));
float dy = f0*lum(tex2D(sampler_main,uv+ver) 
         - tex2D(sampler_main,uv-ver));

float2 zz= float2 (dx,dy);
float3 blur = GetBlur1(uv) ;

zz *= 1-blur;

float3 crisp = tex2D(sampler_main,uv-zz*.02);

crisp += noiseVal*(.12) -0.01*pow(1-rad,4);

ret1 = -blur*.1+ crisp*1.1;

ret = ret1;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((zz.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 
 ret *= 0.97;
  ret -= 0.05;
}

bowel trounce dumring.comp:
shader_body
{
    float rad_lq = rad * length(texsize.xy)*0.5;
    float ang_lq = ang;
    float2 uv_temp1 = (uv - 0.5) * texsize.xy;
    float rad_hq = length(uv_temp1);
    float ang_hq = atan2(-uv_temp1.y, uv_temp1.x);

    float2 uv2 = (uv - 0.5);
    float rad2 = rad_lq*0.8;
    float ang2 = ang_lq * M_INV_PI_2;

        // ROTATION OVER TIME
        #if 1
          ang2 += time*0.025;   //rotate over time
        #endif

        // FIN TYPE
        float fins = 3 + floor(rand_preset.z*5.95);
        #if 1     // SHARP FINS
          ang2 = frac(ang2*fins)/fins;
              // ENABLE THIS TO MAKE THE FINS ALTERNATE: (seamless!)
              ang2 = abs(ang2 - 0.5/fins);
        #else     // COSINE FINS - a bit slow
          ang2 = cos(ang2*M_PI_2*fins) * 0.023;
        #endif

        // RADIAL KALEIDOSCOPING?
        #if 0
          rad2 *= g_fTexSize.z;
            // choose one:
            //rad2 = lerp(rad2, frac(rad2*3)/3.0, 0.5);
            rad2 = cos(rad2*5);
            //rad2 = sqrt(rad2)*0.5;
            //rad2 += abs(frac(rad2*7)-0.5)/7.0 * 1.15;  // stepifier
            //rad2 += cos(rad2*61)*0.02;
          rad2 *= g_fTexSize.x;
        #endif

    ang2 *= M_PI_2;
    uv2 = 0.5 + rad2*float2(cos(ang2),sin(ang2))*texsize.zw;

    ret = tex2D(sampler_main, uv2).xyz;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv2.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
    ret *= 1.333; // a little bit of overbright
ret=.6-ret;
}

