EoS_Phat Dark_heart_nobal_cause cpe ap4+.warp:
shader_body
{


    float3 rc = GetPixel(uv)+GetBlur1(uv);//+GetPixel(uv);
    uv = uv-float2(0,1);
    float2 ruv = 0.5 + (uv-0.5)*(1+(rc.y*0.03));  

    ruv = frac(float2(ruv.x+pow(rc.x,0), ruv.y+pow(rc.x, 0.005)));

    float3 noise3 = tex2D(sampler_noise_lq, uv_orig*texsize.xy*texsize_noise_lq.zw+rand_frame.xy);
    noise3 *= frac(q15);
    noise3 = lerp(noise3, float3(0,0,0), frac(q3*0.5));

    ret = tex2D(sampler_main, float2(ruv.x, ruv.y)).xyz;

    float3 noise2 = lerp(noise3,float3(q10,q11,q12), ret.x);    

    ret += saturate(cross((ret), (noise2)));
    ret *= 1; 
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((ruv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q3         && ret.x<= q24*q1        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q1         && ret.y<= q25*q2        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q2         && ret.z<= q26*q3        )ret.x += (noise9).z*.5; 


}

EoS_Phat Dark_heart_nobal_cause cpe ap4+.comp:
sampler sampler_fw_sky;
shader_body
{
float2 uvm = frac(uv + time*.0);

ret = tex2D(sampler_main,uvm);
float diff = 1-length(ret.xy-GetBlur1(uvm).xy)*3.5;
diff *=1-length(ret.xy-GetBlur2(uvm).xy)*1;
ret.xy *= diff;
ret.z = pow(diff,1/(1-uv.y));

float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q3         && ret.x<= q23*q1        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q1         && ret.y<= q22*q2        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q2         && ret.z<= q21*q3        )ret.y -= (noise9).z*.5; 
}

