vascular acoustic electrical pineal reso.warp:
sampler sampler_fc_colors;
shader_body 
{ 

    float2 zoom = 5;
    float2 c = float2(q4, q5);
    float2 uxy = (float2(uv.x-0.5, uv.y-0.5))*zoom;
    float2 modi = float2(round(q10), round(q11));

    //if a value is 0 add 1 to both, 0's break the effect
    if(all(modi)) {} else {modi = float2(abs(modi.x+1), abs(modi.y)+1);}

    float moduz = sqrt(uxy.x*uxy.x + uxy.y*uxy.y);

    float thetaz = atan2(uxy.y, uxy.x);

    uxy = (float2((pow(moduz, -2)*cos(thetaz*modi.y)), (pow(moduz, -2)*sin(thetaz*modi.y))))+c;
    thetaz = atan2(uxy.y, uxy.x);
    moduz = sqrt(uxy.x*uxy.x + uxy.y*uxy.y);
    uxy = (float2((pow(moduz, -2)*cos(thetaz*modi.y)), (pow(moduz, -2)*sin(thetaz*modi.y))))+c;

    float3 reta = tex2D(sampler_fc_colors, uxy).xyz;    
reta-=slow_roam_sin*roam_cos.wzy*.4;

    ret = reta;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uxy.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 

    ret *= lum(ret)*1.4;
}

vascular acoustic electrical pineal reso.comp:
sampler sampler_manyfish;
shader_body
{
    float2 d = texsize.zw*8;
    float3 dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );
    float2 uv_y = uv-float2(dx.y,dy.y)*0.4;

    float2 uv_dx = uv - float2(dx.x,dy.x)*1;
    float2 uv_dz = uv + float2(dx.z,dy.z)*texsize.zw*256;
    float2 uv_dy = uv - float2(dx.y,dy.y)*texsize.zw*80;

ret = GetPixel(uv).y*0.2;

float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv_dz.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
ret = lerp(float3(0.2,0,0.1),float3(0.8,0.6,0),GetPixel(uv_dz).y); 
ret = lerp(ret,1,GetPixel(uv).z*1);

ret = lerp(ret, float3(0.8,0,1.5), length(float2(dx.x,dy.x)));

ret = lerp(saturate(ret),0,saturate(GetPixel(uv_dz).x-GetBlur1(uv).z*1.5));

//ret = GetPixel(uv).y;
}

