sampler sampler_grad = sampler_state {
 AddressU = WRAP; 
 AddressV = WRAP;
};

sampler sampler_grad2 = sampler_state {
 AddressU = WRAP; 
 AddressV = WRAP;
};


shader_body
{
        float2x2 rot = { cos(-q2) - 0.01, sin(-q2),
                    -sin(-q2), cos(-q2) - 0.01
              };

    float final_noise = 0;

    ret = tex2D(sampler_grad, mul(uv-0.5,rot) + 0.5);
    ret += tex2D(sampler_grad2, mul(uv-0.5,rot) + 0.5);

    float2 uv_echo = (uv - 0.5)*1.000*float2(-1,-1) + 0.5;
    float3 output =  tex2D(sampler_main, uv).xyz;
    float3 blur =  tex2D(sampler_main, GetBlur1(uv)).xyz;

    ret *= cross(blur,output);
    ret = pow(ret,0.9);
    ret *= 1000.00; //gamma

}

